INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (1, 'Godsdiensten', 'medium', 'Wat is een godsdienst?', '["Een politieke partij met vaste regels.","Een school waar je over geschiedenis leert.","Een wetenschappelijke theorie over het ontstaan van de wereld.","Een geloof in een god of meerdere goden en de bijbehorende tradities."]', 3, 'Een godsdienst is een geloof in een god of goden, met bijbehorende tradities.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (2, 'Godsdiensten', 'medium', 'Welke godsdienst heeft Jezus als centrale figuur?', '["Het christendom.","Het boeddhisme.","Het jodendom.","De islam."]', 0, 'Voor christenen is Jezus de centrale figuur.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (3, 'Godsdiensten', 'medium', 'Wat is het heilige boek van de christenen?', '["De Bijbel.","De Koran.","De Thora.","De Veda''s."]', 0, 'De Bijbel bestaat uit het Oude en het Nieuwe Testament.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (4, 'Godsdiensten', 'medium', 'Wat is het heilige boek van de moslims?', '["De Tripitaka.","De Thora.","De Koran.","De Bijbel."]', 2, 'De Koran is het heilige boek van de islam.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (5, 'Godsdiensten', 'medium', 'Hoe heet de god van de islam?', '["Jahweh.","Zeus.","Brahma.","Allah."]', 3, 'Moslims noemen hun god Allah.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (6, 'Godsdiensten', 'medium', 'Wie is de profeet van de islam?', '["Mozes.","Abraham.","Mohammed.","Boeddha."]', 2, 'Mohammed is de laatste profeet in de islam.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (7, 'Godsdiensten', 'medium', 'Wat is het heilige boek van het jodendom?', '["De Bhagavad Gita.","De Koran.","De Thora.","Het Nieuwe Testament."]', 2, 'De Thora bevat de eerste vijf boeken van het Oude Testament.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (8, 'Godsdiensten', 'medium', 'Hoe heet de gebedsplaats van moslims?', '["Een moskee.","Een tempel.","Een synagoge.","Een kerk."]', 0, 'Moslims bidden in een moskee.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (9, 'Godsdiensten', 'medium', 'Hoe heet de gebedsplaats van christenen?', '["Een moskee.","Een kerk.","Een synagoge.","Een pagode."]', 1, 'Christenen komen samen in een kerk.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (10, 'Godsdiensten', 'medium', 'Hoe heet de gebedsplaats van joden?', '["Een klooster.","Een moskee.","Een synagoge.","Een kerk."]', 2, 'Joden bidden in een synagoge.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (11, 'Godsdiensten', 'medium', 'Welke godsdienst heeft Brahman als belangrijk godsbegrip?', '["Het christendom.","Het hindoeïsme.","Het boeddhisme.","De islam."]', 1, 'In het hindoeïsme is Brahman het hoogste, allesomvattende goddelijke principe.', '["quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (12, 'Godsdiensten', 'medium', 'Wie was Siddhartha Gautama?', '["Een hindoeïstische god.","De profeet van de islam.","De Boeddha, de stichter van het boeddhisme.","Een Joodse rabbijn."]', 2, 'Siddhartha Gautama werd de Boeddha, de ''verlichte''.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (13, 'Godsdiensten', 'medium', 'Wat is de Kaäba?', '["Een heilige plaats in Mekka waar moslims naartoe bidden.","Een islamitisch feest.","Een moskee in Jeruzalem.","Het heilige boek van de islam."]', 0, 'Moslims richten zich tijdens het gebed naar de Kaäba in Mekka.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (14, 'Godsdiensten', 'medium', 'Wat vieren christenen met Kerstmis?', '["Het einde van de vastentijd.","De komst van de Heilige Geest.","De verrijzenis van Jezus.","De geboorte van Jezus."]', 3, 'Met Kerstmis vieren christenen de geboorte van Jezus.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (15, 'Godsdiensten', 'medium', 'Wat vieren christenen met Pasen?', '["De komst van de Heilige Geest.","De doop van Jezus.","De geboorte van Jezus.","De verrijzenis van Jezus."]', 3, 'Met Pasen vieren christenen dat Jezus uit de dood is opgestaan.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (16, 'Godsdiensten', 'medium', 'Wat vieren moslims tijdens het Suikerfeest?', '["Het einde van de vastenmaand Ramadan.","De geboorte van Mohammed.","Het begin van het nieuwe jaar.","De bedevaart naar Mekka."]', 0, 'Het Suikerfeest sluit de vastenmaand Ramadan af.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (17, 'Godsdiensten', 'medium', 'Wat is de Ramadan?', '["Een maand waarin moslims overdag vasten.","Een bedevaart naar Mekka.","Een dagelijks gebed.","Een islamitisch feest met offers."]', 0, 'Tijdens de Ramadan eten en drinken moslims overdag niet.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (18, 'Godsdiensten', 'medium', 'Wat is de sjabbat?', '["Een joods nieuwjaarsfeest.","De joodse naam voor de synagoge.","Een joods gebedsboek.","De wekelijkse rustdag in het jodendom."]', 3, 'De sjabbat is de wekelijkse rustdag van vrijdagavond tot zaterdagavond.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (19, 'Godsdiensten', 'medium', 'Wat is een imam?', '["Een boeddhistische monnik.","Een christelijke priester.","Een voorganger die het gebed in een moskee kan leiden.","Een joodse leraar."]', 2, 'Een imam leidt het gebed in de moskee.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (20, 'Godsdiensten', 'medium', 'Wat is een rabbijn?', '["Een hindoeïstische priester.","Een joodse religieuze leraar.","Een islamitische voorganger.","Een katholieke bisschop."]', 1, 'Een rabbijn is een leraar en leider in het jodendom.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (21, 'Sacramenten', 'medium', 'Hoeveel sacramenten zijn er in de katholieke Kerk?', '["Drie.","Vijf.","Zeven.","Twaalf."]', 2, 'De katholieke Kerk kent zeven sacramenten.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (22, 'Sacramenten', 'medium', 'Wat is het eerste sacrament dat iemand meestal ontvangt?', '["Het doopsel.","Het vormsel.","De eerste communie.","Het huwelijk."]', 0, 'Het doopsel is meestal het eerste sacrament.', '["quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (23, 'Sacramenten', 'medium', 'Wat gebeurt er bij een doopsel?', '["Iemand wordt opgenomen in de christelijke gemeenschap.","Iemand krijgt vergeving van zijn zonden na een biecht.","Twee mensen beloven elkaar trouw.","Iemand wordt priester gewijd."]', 0, 'Door het doopsel word je opgenomen in de christelijke gemeenschap.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (24, 'Sacramenten', 'medium', 'Welk symbool wordt gebruikt bij het doopsel?', '["Water.","Olie.","Vuur.","Brood."]', 0, 'Water is het teken van reiniging en nieuw leven.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (25, 'Sacramenten', 'medium', 'Wat betekent het vormsel?', '["De opname in de kerk.","Een bevestiging van het geloof en de doopbelofte.","Een eerste biecht.","Een zegen voor zieken."]', 1, 'Bij het vormsel bevestig je zelf je geloof en de doopbelofte.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (26, 'Sacramenten', 'medium', 'Welk sacrament heeft te maken met brood en wijn?', '["De ziekenzalving.","De eucharistie.","Het doopsel.","De biecht."]', 1, 'Bij de eucharistie delen gelovigen brood en wijn.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (27, 'Sacramenten', 'medium', 'Wat stelt het brood voor tijdens de eucharistie?', '["De Heilige Geest.","Het bloed van Christus.","De apostelen.","Het lichaam van Christus."]', 3, 'Het brood staat voor het lichaam van Christus.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (28, 'Sacramenten', 'medium', 'Wat stelt de wijn voor tijdens de eucharistie?', '["Het water van de Jordaan.","Het bloed van Christus.","Het lichaam van Christus.","De tranen van Maria."]', 1, 'De wijn staat voor het bloed van Christus.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (29, 'Sacramenten', 'medium', 'Welk sacrament wordt ook de biecht genoemd?', '["De verzoening of vergeving.","De eucharistie.","De wijding.","Het vormsel."]', 0, 'Bij de biecht vraag je vergeving en word je verzoend.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (30, 'Sacramenten', 'medium', 'Wat gebeurt er bij de ziekenzalving?', '["Een zieke of stervende persoon ontvangt gebed, steun en zalving met olie.","Een kind krijgt voor het eerst de communie.","Een persoon wordt gedoopt met water.","Een priester biecht zijn zonden op."]', 0, 'Bij de ziekenzalving ontvangt een zieke gebed, steun en olie.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (31, 'Sacramenten', 'medium', 'Welk sacrament verbindt twee mensen in een christelijk huwelijk?', '["Het vormsel.","Het huwelijk.","De wijding.","Het doopsel."]', 1, 'In het sacrament van het huwelijk beloven twee mensen elkaar trouw.', '["quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (32, 'Sacramenten', 'medium', 'Wat is het sacrament van de wijding?', '["Het sacrament waardoor iemand diaken, priester of bisschop wordt.","Het sacrament waarbij je gedoopt wordt.","Het sacrament voor zieke mensen.","Het sacrament van het christelijk huwelijk."]', 0, 'Door de wijding word je diaken, priester of bisschop.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (33, 'Sacramenten', 'medium', 'Wie dient meestal het doopsel toe?', '["De pastoor van een ander dorp.","De peter of meter.","Een bisschop alleen.","Een priester of diaken."]', 3, 'Meestal dient een priester of diaken het doopsel toe.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (34, 'Sacramenten', 'medium', 'Wat is heilig water?', '["Water dat nooit bederft.","Water uit de Jordaan.","Water dat door een priester is gezegend.","Water dat alleen in de kerk gedronken wordt."]', 2, 'Heilig water is water dat een priester heeft gezegend.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (35, 'Sacramenten', 'medium', 'Wat is de eerste communie?', '["De eerste keer dat iemand biecht.","De eerste keer dat een kind gedoopt wordt.","De eerste keer dat een kind deelneemt aan de eucharistie en de communie ontvangt.","De dag waarop een kind gevormd wordt."]', 2, 'Bij de eerste communie ontvangt een kind voor het eerst de eucharistie.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (36, 'Christendom', 'medium', 'Wie is Jezus?', '["Een profeet in de islam die alleen in de Koran voorkomt.","De centrale figuur van het christendom en voor christenen de Zoon van God.","De eerste paus van de katholieke Kerk.","De stichter van het jodendom."]', 1, 'Voor christenen is Jezus de Zoon van God.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (37, 'Christendom', 'medium', 'Wie was Maria?', '["De moeder van Jezus.","De eerste vrouw van Adam.","De vrouw van Petrus.","De zus van Mozes."]', 0, 'Maria is de moeder van Jezus.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (38, 'Christendom', 'medium', 'Wie was Jozef?', '["Een van de twaalf apostelen.","De man van Maria en de opvoedvader van Jezus.","De koning van Bethlehem.","De broer van Jezus."]', 1, 'Jozef was de man van Maria en de opvoedvader van Jezus.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (39, 'Christendom', 'medium', 'Waar werd Jezus volgens de Bijbel geboren?', '["In Jeruzalem.","In Nazareth.","In Rome.","In Bethlehem."]', 3, 'Volgens de Bijbel werd Jezus in Bethlehem geboren.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (40, 'Christendom', 'medium', 'Waar groeide Jezus op?', '["In Bethlehem.","In Jeruzalem.","In Egypte.","In Nazareth."]', 3, 'Jezus groeide op in Nazareth.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (41, 'Christendom', 'medium', 'Hoeveel apostelen had Jezus?', '["Zeventig.","Tien.","Twaalf.","Zeven."]', 2, 'Jezus riep twaalf apostelen.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (42, 'Christendom', 'medium', 'Wie heeft Jezus verraden?', '["Judas Iskariot.","Petrus.","Johannes.","Pilatus."]', 0, 'Judas Iskariot leverde Jezus uit.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (43, 'Christendom', 'medium', 'Wie was Petrus?', '["Een Romeinse keizer.","Een joodse profeet.","Een van Jezus'' apostelen.","De moeder van Jezus."]', 2, 'Petrus was een van de apostelen van Jezus.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (44, 'Christendom', 'medium', 'Wat is de kruisiging?', '["De doop van Jezus in de Jordaan.","De terechtstelling van Jezus aan het kruis.","De geboorte van Jezus in de stal.","Het laatste avondmaal."]', 1, 'Bij de kruisiging werd Jezus aan het kruis terechtgesteld.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (45, 'Christendom', 'medium', 'Wat betekent verrijzenis?', '["Dat Jezus werd geboren.","Dat Jezus volgens het christelijk geloof uit de dood is opgestaan.","Dat Jezus werd gedoopt.","Dat Jezus naar de hemel is opgevaren."]', 1, 'Verrijzenis is het opstaan van Jezus uit de dood.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (46, 'Christendom', 'medium', 'Wat is Pinksteren?', '["Het feest van alle heiligen.","Het feest van de geboorte van Jezus.","Het feest waarop christenen de komst van de Heilige Geest vieren.","Het feest van de opstanding."]', 2, 'Met Pinksteren vieren christenen de komst van de Heilige Geest.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (47, 'Christendom', 'medium', 'Wat is de Drie-eenheid?', '["De drie belangrijkste feesten.","De drie boeken van het Nieuwe Testament.","God als Vader, Zoon en Heilige Geest.","De drie koningen bij de kribbe."]', 2, 'De Drie-eenheid is God als Vader, Zoon en Heilige Geest.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (48, 'Christendom', 'medium', 'Wie is de paus?', '["De hoogste rabbijn.","Het hoofd van de katholieke Kerk.","De leider van de islam.","De burgemeester van Rome."]', 1, 'De paus is het hoofd van de katholieke Kerk.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (49, 'Christendom', 'medium', 'Wat is een priester?', '["Een monnik die nooit spreekt.","Een geestelijke die onder andere de mis kan voorgaan.","Een bisschop van een grote stad.","Een leraar in de synagoge."]', 1, 'Een priester gaat onder andere voor in de mis.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (50, 'Christendom', 'medium', 'Wat is een klooster?', '["Een school voor priesters.","Een bedevaartsplaats.","Een kerk waar alleen gedoopt wordt.","Een plaats waar monniken of zusters samen religieus leven."]', 3, 'In een klooster leven monniken of zusters samen.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (51, 'Levensbeschouwingen', 'medium', 'Wat is een levensbeschouwing?', '["Een gebouw waar mensen bidden.","Een wetenschappelijk experiment.","Een gebed voor het eten.","Een manier waarop iemand naar het leven en de wereld kijkt."]', 3, 'Een levensbeschouwing is je kijk op het leven en de wereld.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (52, 'Levensbeschouwingen', 'medium', 'Wat is een atheïst?', '["Iemand die in meerdere goden gelooft.","Iemand die niet weet of er een god bestaat.","Iemand die de mens centraal stelt.","Iemand die niet in een god of goden gelooft."]', 3, 'Een atheïst gelooft niet in een god of goden.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (53, 'Levensbeschouwingen', 'medium', 'Wat is een gelovige?', '["Iemand die gelooft in een god of een religieuze overtuiging aanhangt.","Iemand die niet in een god gelooft.","Iemand die in een kerk werkt.","Iemand die nooit twijfelt."]', 0, 'Een gelovige hangt een religieuze overtuiging aan.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (54, 'Levensbeschouwingen', 'medium', 'Wat is een agnost?', '["Iemand die elke dag bidt.","Iemand die niet weet of we kunnen weten of er een god bestaat.","Iemand die zeker weet dat er geen god is.","Iemand die priester wil worden."]', 1, 'Een agnost twijfelt of we kunnen weten of er een god bestaat.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (55, 'Levensbeschouwingen', 'medium', 'Wat betekent respect?', '["Dat je anderen laat doen wat jij wilt.","Dat je anderen aanvaardt en rekening houdt met hun gevoelens en overtuigingen.","Dat je altijd dezelfde mening hebt als de ander.","Dat je bang bent voor anderen."]', 1, 'Respect is anderen aanvaarden en rekening houden met hen.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (56, 'Levensbeschouwingen', 'medium', 'Wat is verdraagzaamheid?', '["Dat je alleen met gelijkgezinden omgaat.","Dat je andere meningen, culturen en overtuigingen respecteert.","Dat je iedereen overtuigt van jouw mening.","Dat je andere meningen negeert."]', 1, 'Verdraagzaamheid is andere meningen en culturen respecteren.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (57, 'Levensbeschouwingen', 'medium', 'Wat is een ritueel?', '["Een handeling die volgens vaste gewoontes of regels wordt uitgevoerd.","Een spontane vraag aan een leraar.","Een boek met regels.","Een soort feestdag."]', 0, 'Een ritueel volgt vaste gewoontes of regels.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (58, 'Levensbeschouwingen', 'medium', 'Wat is een symbool?', '["Een woord uit een heilig boek.","Een teken of voorwerp dat een bepaalde betekenis heeft.","Een gebouw voor religieuze samenkomsten.","Een verhaal met een les."]', 1, 'Een symbool verwijst naar een bepaalde betekenis, zoals het kruis.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (59, 'Levensbeschouwingen', 'medium', 'Wat betekent solidariteit?', '["Dat je veel geld bezit.","Dat je alleen aan jezelf denkt.","Dat je altijd wint.","Dat je anderen steunt en helpt."]', 3, 'Solidariteit is anderen steunen en helpen.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (60, 'Levensbeschouwingen', 'medium', 'Wat is discriminatie?', '["Iemand eerlijk behandelen.","Iemand helpen met zijn huiswerk.","Iemand een compliment geven.","Iemand ongelijk behandelen op basis van bijvoorbeeld afkomst, geloof of geslacht."]', 3, 'Bij discriminatie behandel je iemand ongelijk om bijvoorbeeld zijn afkomst.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (61, 'Levensbeschouwingen', 'medium', 'Wat is een humanist?', '["Iemand die alleen in één god gelooft.","Iemand die voor een kerk werkt.","Iemand die niet nadenkt over het leven.","Iemand die de mens, menselijke waardigheid en verantwoordelijkheid centraal stelt."]', 3, 'Een humanist stelt de mens en zijn waardigheid centraal.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (62, 'Levensbeschouwingen', 'medium', 'Wat is een waarde?', '["Een prijs die je voor iets betaalt.","Iets wat iemand belangrijk vindt in het leven.","Een regel van de school.","Een heilig voorwerp."]', 1, 'Een waarde is iets wat je belangrijk vindt, zoals eerlijkheid.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (63, 'Levensbeschouwingen', 'medium', 'Wat is een norm?', '["Iets wat je heel belangrijk vindt.","Een regel of afspraak over hoe mensen zich gedragen.","Een religieus feest.","Een soort gebed."]', 1, 'Een norm is een regel of afspraak over gedrag.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (64, 'Levensbeschouwingen', 'medium', 'Wat is vrijheid van godsdienst?', '["Het recht om andere godsdiensten te verbieden.","Het recht om zelf een godsdienst te kiezen, te veranderen of niet te geloven.","De plicht om elke week naar de kerk te gaan.","Het recht om anderen je geloof op te leggen."]', 1, 'Je mag zelf kiezen of en wat je gelooft.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (65, 'Levensbeschouwingen', 'medium', 'Wat betekent geweten?', '["Een gebed om vergeving.","Een wet van de overheid.","Het innerlijke besef van wat je goed of fout vindt.","Alles wat je op school leert."]', 2, 'Je geweten zegt je wat je goed of fout vindt.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (66, 'Bijbel', 'medium', 'Uit hoeveel grote delen bestaat de Bijbel?', '["Twee: het Oude Testament en het Nieuwe Testament.","Vier: de vier evangeliën.","Drie: de Thora, de Psalmen en de Evangeliën.","Zeven: één voor elk sacrament."]', 0, 'De Bijbel bestaat uit het Oude en het Nieuwe Testament.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (67, 'Bijbel', 'medium', 'Hoe heet het eerste boek van de Bijbel?', '["Psalmen.","Exodus.","Genesis.","Mattheüs."]', 2, 'Genesis, ''het begin'', vertelt het scheppingsverhaal.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (68, 'Bijbel', 'medium', 'Wie waren Adam en Eva?', '["De kinderen van Noach.","De ouders van Jezus.","De eerste mensen volgens het scheppingsverhaal.","De twee eerste apostelen."]', 2, 'Adam en Eva zijn de eerste mensen in het scheppingsverhaal.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (69, 'Bijbel', 'medium', 'Wie bouwde volgens de Bijbel een ark?', '["Noach.","Abraham.","David.","Mozes."]', 0, 'Noach bouwde de ark om mens en dier te redden van de zondvloed.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (70, 'Bijbel', 'medium', 'Wie leidde volgens de Bijbel het volk Israël uit Egypte?', '["Mozes.","Jozef.","Abraham.","David."]', 0, 'Mozes leidde het volk Israël uit Egypte.', '["quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (71, 'Bijbel', 'medium', 'Wat zijn de tien geboden?', '["De tien plagen van Egypte.","Tien gebeden van Jezus.","Tien belangrijke leefregels uit de Bijbel.","Tien boeken van de Bijbel."]', 2, 'De tien geboden zijn tien belangrijke leefregels.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (72, 'Bijbel', 'medium', 'Wie versloeg Goliath?', '["Samson.","David.","Mozes.","Petrus."]', 1, 'De jonge David versloeg de reus Goliath.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (73, 'Bijbel', 'medium', 'Wat is een parabel?', '["Een gebed om vergeving.","Een geschiedenis van een koning.","Een kort verhaal met een levensles of diepere betekenis.","Een heilig gebouw."]', 2, 'Een parabel is een kort verhaal met een levensles.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (74, 'Bijbel', 'medium', 'Wat leert de parabel van de barmhartige Samaritaan?', '["Dat je nooit mag reizen.","Dat je alleen je familie moet helpen.","Dat je iedereen moet helpen, ook mensen die anders zijn.","Dat je altijd moet sparen."]', 2, 'Je helpt iedereen die hulp nodig heeft, ook als die anders is.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (75, 'Bijbel', 'medium', 'Wat is het Onzevader?', '["Een belangrijk gebed dat Jezus aan zijn leerlingen leerde.","Een psalm van koning David.","Het eerste boek van de Bijbel.","Een gebed voor Maria."]', 0, 'Het Onzevader is het gebed dat Jezus aan zijn leerlingen leerde.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (76, 'Islam', 'medium', 'Hoeveel zuilen heeft de islam?', '["Drie.","Vijf.","Zeven.","Tien."]', 1, 'De islam kent vijf zuilen.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (77, 'Islam', 'medium', 'Wat is de eerste zuil van de islam?', '["Het vasten.","De bedevaart.","Het gebed.","De geloofsbelijdenis."]', 3, 'De eerste zuil is de geloofsbelijdenis (sjahada).', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (78, 'Islam', 'medium', 'Hoe vaak per dag bidden moslims traditioneel?', '["Eén keer.","Vijf keer.","Zeven keer.","Drie keer."]', 1, 'Moslims bidden traditioneel vijf keer per dag.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (79, 'Islam', 'medium', 'In welke stad ligt de Kaäba?', '["Caïro.","Medina.","Jeruzalem.","Mekka."]', 3, 'De Kaäba staat in Mekka.', '["memory","quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (80, 'Islam', 'medium', 'Wat is de hadj?', '["De bedevaart naar Mekka.","De vastenmaand.","Een islamitisch feest met offers.","Het islamitische gebed."]', 0, 'De hadj is de bedevaart naar Mekka.', '["memory","quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (81, 'Islam', 'medium', 'Wat is halal?', '["Wat volgens de islamitische regels verboden is.","Wat volgens de islamitische regels toegestaan is.","Een feestmaaltijd.","Een islamitisch gebedskleed."]', 1, 'Halal betekent toegestaan volgens de islamitische regels.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (82, 'Islam', 'medium', 'Wat betekent haram?', '["Een islamitisch feest.","Een voorganger in de moskee.","Wat volgens de islamitische regels toegestaan is.","Wat volgens de islamitische regels verboden is."]', 3, 'Haram betekent verboden volgens de islamitische regels.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (83, 'Islam', 'medium', 'Wat is het Offerfeest?', '["Het feest na de Ramadan.","Het feest van de geboorte van Mohammed.","Een belangrijk islamitisch feest dat verbonden is met het verhaal van Abraham.","Het islamitische nieuwjaar."]', 2, 'Het Offerfeest herinnert aan het verhaal van Abraham.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (84, 'Hindoeïsme en boeddhisme', 'medium', 'Wat betekent karma?', '["Dat je na je dood naar de hemel gaat.","Dat je elke dag moet bidden.","Dat iedereen dezelfde kansen heeft.","Het idee dat je daden gevolgen hebben."]', 3, 'Volgens karma hebben je daden gevolgen.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (85, 'Hindoeïsme en boeddhisme', 'medium', 'Wat is reïncarnatie?', '["Het geloof dat je ziel in een boek wordt opgeschreven.","Het geloof dat je na je dood in de hemel komt.","Het geloof dat de ziel verdwijnt.","Het geloof dat iemand na de dood opnieuw geboren wordt."]', 3, 'Bij reïncarnatie wordt iemand na de dood opnieuw geboren.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (86, 'Hindoeïsme en boeddhisme', 'medium', 'Wat is nirwana?', '["Een heilig boek.","Een toestand waarin je bevrijd bent van lijden en verlangens.","Een plaats waar je gestraft wordt.","Een tempel in India."]', 1, 'Nirwana is bevrijding van lijden en verlangens.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (87, 'Hindoeïsme en boeddhisme', 'medium', 'Welk dier wordt in het hindoeïsme vaak als heilig beschouwd?', '["De duif.","De koe.","Het varken.","De hond."]', 1, 'Hindoes beschouwen de koe vaak als heilig.', '["quiz","faithrunner"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (88, 'Hindoeïsme en boeddhisme', 'medium', 'Wat is meditatie?', '["Een vorm van vasten.","Een oefening om je aandacht en gedachten tot rust te brengen.","Een manier om hard te bidden.","Een religieus feest."]', 1, 'Meditatie brengt je aandacht en gedachten tot rust.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (89, 'Hindoeïsme en boeddhisme', 'medium', 'Wat is een mantra?', '["Een heilige rivier.","Een goddelijk beeld.","Een soort tempel.","Een woord, klank of zin die herhaald wordt tijdens meditatie of gebed."]', 3, 'Een mantra herhaal je tijdens meditatie of gebed.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (90, 'Hindoeïsme en boeddhisme', 'medium', 'Wat betekent ahimsa?', '["Het vieren van een feest.","Het offeren van dieren.","Geweldloosheid en respect voor alle levende wezens.","Het bidden in de ochtend."]', 2, 'Ahimsa betekent geweldloosheid.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (91, 'Algemene kennis', 'medium', 'Wat is een bedevaart?', '["Een feest in de kerk.","Een dagelijks gebed.","Een tijd van vasten.","Een religieuze reis naar een heilige plaats."]', 3, 'Een bedevaart is een religieuze reis naar een heilige plaats.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (92, 'Algemene kennis', 'medium', 'Wat is een feestdag in een godsdienst?', '["Een dag waarop niemand mag bidden.","Een gewone werkdag.","Een speciale dag waarop gelovigen iets belangrijks herdenken of vieren.","Een dag om te vasten."]', 2, 'Op een feestdag herdenken of vieren gelovigen iets belangrijks.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (93, 'Algemene kennis', 'medium', 'Wat is vasten?', '["Een bepaalde tijd minder of niet eten en soms drinken om religieuze of persoonlijke redenen.","Een gebed zingen.","Een feestmaaltijd houden.","Een dier offeren."]', 0, 'Bij vasten eet of drink je een tijdlang minder of niets.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (94, 'Algemene kennis', 'medium', 'Wat is bidden?', '["Een bedevaart maken.","Een feest vieren.","Een boek lezen.","Praten met God of een hogere macht."]', 3, 'Bidden is praten met God of een hogere macht.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (95, 'Algemene kennis', 'medium', 'Wat is een geestelijke?', '["Iemand met een religieuze functie binnen een godsdienst.","Een lid van het leger.","Iemand die een feest organiseert.","Iemand die niet in God gelooft."]', 0, 'Een geestelijke heeft een religieuze functie.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (96, 'Algemene kennis', 'medium', 'Wat is een heilige?', '["Iemand die nooit fouten maakt.","Iemand die binnen een godsdienst als bijzonder voorbeeldig of heilig wordt beschouwd.","Iemand die priester is.","Een engel in de hemel."]', 1, 'Een heilige is een bijzonder voorbeeld voor gelovigen.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (97, 'Algemene kennis', 'medium', 'Wat is een religieus feest?', '["Een feest dat verbonden is met een godsdienstige gebeurtenis of overtuiging.","Een verjaardagsfeest.","Een nationale feestdag.","Een schoolfeest."]', 0, 'Een religieus feest hoort bij een godsdienstige gebeurtenis.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (98, 'Algemene kennis', 'medium', 'Wat betekent interreligieuze dialoog?', '["Een gesprek tussen mensen van verschillende godsdiensten.","Een gebed in meerdere talen.","Een gesprek tussen atheïsten.","Een ruzie tussen twee gelovigen."]', 0, 'Bij interreligieuze dialoog praten mensen van verschillende godsdiensten met elkaar.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (99, 'Algemene kennis', 'medium', 'Waarom is respect tussen verschillende godsdiensten belangrijk?', '["Om minder naar school te moeten.","Om iedereen dezelfde godsdienst te laten volgen.","Om verschillen weg te werken.","Om vreedzaam samen te leven en elkaar beter te begrijpen."]', 3, 'Met respect leef je vreedzaam samen en begrijp je elkaar beter.', '["quiz"]');
INSERT INTO questions (id, category, difficulty, question, answers, correct, explanation, suitable) VALUES (100, 'Algemene kennis', 'medium', 'Kun je respectvol omgaan met iemand die niet in God gelooft?', '["Alleen als die persoon ook bidt.","Alleen als je dezelfde overtuiging hebt.","Nee, dat kan alleen met gelovigen.","Ja, iedereen verdient respect, ongeacht zijn of haar overtuiging."]', 3, 'Iedereen verdient respect, ongeacht zijn of haar overtuiging.', '["quiz"]');
